<?php
namespace App\Console\Commands;
use App\Services\Shipping\{ProviderStrategyResolver,UnifiedShippingQuoteService};use App\Services\Shipping\Data\UnifiedQuoteRequest;use App\Services\Shipping\Diagnostics\ShippingContractRecorder;use Illuminate\Console\Command;use Illuminate\Support\Facades\Storage;
final class ShippingProbeCommand extends Command {protected $signature='zigo:shipping-probe {--environment=stage} {--carrier=estafeta} {--operation=all} {--cp-origin=64000} {--cp-destination=64000} {--weight=1} {--length=20} {--width=20} {--height=20} {--package-type=box} {--confirm=} {--record-contract} {--dry-run}';protected $description='Probe técnico no comercial de cobertura/cotización Stage.';public function handle(ProviderStrategyResolver $resolver,UnifiedShippingQuoteService $quotes,ShippingContractRecorder $recorder):int{if($this->option('environment')!=='stage'){$this->error('Production está prohibido en EST-PRD-03.');return self::INVALID;}$decision=$resolver->resolve('quote',(string)$this->option('carrier'),'stage');$execute=$this->option('confirm')==='SHIPPING-STAGE'&&!$this->option('dry-run');$result=null;if($execute&&$decision['strategy']!=='unavailable'){$request=new UnifiedQuoteRequest('estafeta',(string)$this->option('cp-origin'),(string)$this->option('cp-destination'),(float)$this->option('weight'),(float)$this->option('length'),(float)$this->option('width'),(float)$this->option('height'),(string)$this->option('package-type'));if($this->option('record-contract'))config(['services.shipping.contract_recorder_enabled'=>true]);$result=$recorder->record(['provider'=>$decision['http_provider']??'none','operation'=>'quote','method'=>'POST','caller'=>self::class,'environment'=>'stage','request'=>$request->toArray()],fn()=>$quotes->quote($request,'stage',true)->toArray());}$ready=$result!==null&&($result['success']??false)&&$decision['strategy']==='xperta_estafeta';$report=['generated_at'=>now()->toIso8601String(),'strategy'=>$decision,'external_call_executed'=>$execute,'dry_run'=>(bool)$this->option('dry-run'),'result'=>$result,'READY_FOR_B2C_QUOTE_ADAPTER'=>$ready];$path='private/shipping-probes/probe-'.now()->format('Ymd-His').'.json';Storage::disk('local')->put($path,json_encode($report,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES));$this->line('Reporte: storage/app/'.$path);$this->line('READY_FOR_B2C_QUOTE_ADAPTER='.($ready?'true':'false'));return self::SUCCESS;}}
